/// <summary>
/// A value written into a table field when the environment is refreshed.
/// </summary>
public class BDRFieldValue extends common
{
}

Method.Source:
    public boolean validateField(FieldId _fieldId)
    {
        boolean ret = super(_fieldId);
        TableId tableId = tableName2Id(this.TableName);

        switch (_fieldId)
        {
            case fieldNum(BDRFieldValue, TableName):
                if (this.TableName && !tableId)
                {
                    ret = checkFailed(strFmt("@BDR:ErrInvalidTable", this.TableName));
                }
                else if (tableId)
                {
                    // The lookup leaves these out; a typed name must not get through either.
                    DictTable dictTable = new DictTable(tableId);

                    // TableType covers in-memory and TempDB tables; isTmp() alone misses TempDB.
                    if (dictTable.tableType() != TableType::Regular || dictTable.isView() || dictTable.isMap() || dictTable.isSystemTable())
                    {
                        ret = checkFailed(strFmt("@BDR:ErrTableNotWritable", this.TableName));
                    }
                }
                break;

            case fieldNum(BDRFieldValue, FieldName):
                if (this.FieldName && tableId && !fieldName2Id(tableId, this.FieldName))
                {
                    ret = checkFailed(strFmt("@BDR:ErrInvalidField", this.FieldName, this.TableName));
                }
                else if (this.FieldName && tableId && new DictField(tableId, fieldName2Id(tableId, this.FieldName)).isSystem())
                {
                    // RecId, DataAreaId, RecVersion and the like: the lookup hides them, a typed name must not get through.
                    ret = checkFailed(strFmt("@BDR:ErrSystemField", this.FieldName, this.TableName));
                }
                break;

            case fieldNum(BDRFieldValue, KeyFieldName):
                if (this.KeyFieldName && tableId && !fieldName2Id(tableId, this.KeyFieldName))
                {
                    ret = checkFailed(strFmt("@BDR:ErrInvalidField", this.KeyFieldName, this.TableName));
                }
                break;
        }

        return ret;
    }

    public boolean validateWrite()
    {
        boolean ret = super();

        ret = this.validateField(fieldNum(BDRFieldValue, TableName)) && ret;
        ret = this.validateField(fieldNum(BDRFieldValue, FieldName)) && ret;
        ret = this.validateField(fieldNum(BDRFieldValue, KeyFieldName)) && ret;

        if (this.SecretName && this.FieldValue)
        {
            ret = checkFailed("@BDR:ErrValueAndSecret") && ret;
        }

        // The value (unless it comes from a secret at run time) and the key value must fit their fields.
        TableId tableId = tableName2Id(this.TableName);
        FieldId fieldId = tableId ? fieldName2Id(tableId, this.FieldName) : 0;
        FieldId keyFieldId = tableId && this.KeyFieldName ? fieldName2Id(tableId, this.KeyFieldName) : 0;

        if (fieldId && BDRTaskTypeFieldValues::isEncryptedField(tableId, fieldId))
        {
            // The setup is stored as plain text, so an encrypted field only takes a pipeline secret.
            if (!this.SecretName)
            {
                ret = checkFailed(strFmt("@BDR:ErrEncryptedFieldNeedsSecret", this.TableName, this.FieldName)) && ret;
            }
        }
        else if (fieldId && !BDRTaskTypeFieldValues::isTypeSupported(tableId, fieldId))
        {
            // Checked without the value as well: a secret only arrives at run time.
            ret = checkFailed(strFmt("@BDR:ErrFieldTypeNotSupported", this.TableName, this.FieldName)) && ret;
        }
        else if (fieldId && !this.SecretName && !BDRTaskTypeFieldValues::canConvert(tableId, fieldId, this.FieldValue))
        {
            ret = checkFailed(strFmt("@BDR:ErrValueNotConvertible", this.FieldValue, this.TableName, this.FieldName)) && ret;
        }

        if (keyFieldId && !BDRTaskTypeFieldValues::canConvert(tableId, keyFieldId, this.KeyValue))
        {
            ret = checkFailed(strFmt("@BDR:ErrValueNotConvertible", this.KeyValue, this.TableName, this.KeyFieldName)) && ret;
        }

        return ret;
    }

    public void initValue()
    {
        super();

        this.AllCompanies = NoYes::Yes;
    }

    public void insert()
    {
        // The same rule as update(): a shared table is always for all companies (also for copied rows).
        if (!this.canChooseCompanies())
        {
            this.AllCompanies = NoYes::Yes;
        }

        super();
    }

    public void update()
    {
        if (!this.canChooseCompanies())
        {
            this.AllCompanies = NoYes::Yes;
        }

        super();

        // All companies replaces the list of selected companies.
        if (this.AllCompanies)
        {
            BDRSetupCompany::deleteFor(this);
        }
    }

/// <summary>
/// The companies this row applies to.
/// </summary>
/// <returns>A set of company IDs.</returns>
public Set companies()
{
    return BDRSetupCompany::companies(this);
}

/// <summary>
/// The selected companies; empty when the row is for all companies.
/// </summary>
public display Description companyScope()
{
    return BDRSetupCompany::scope(this);
}

    /// <summary>
    /// Checks whether the table of the row is shared by all companies.
    /// </summary>
    /// <returns>True for a table that is not saved per company.</returns>
    public boolean isSharedTable()
    {
        TableId tableId = tableName2Id(this.TableName);

        return tableId && !new DictTable(tableId).dataPrCompany();
    }

/// <summary>
/// Companies can only be chosen for a table that is saved per company.
/// </summary>
/// <returns>True if the row can be limited to selected companies.</returns>
public boolean canChooseCompanies()
{
    return this.TableName && !this.isSharedTable();
}

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(BDRFieldValue, TableName):
                if (!this.canChooseCompanies())
                {
                    this.AllCompanies = NoYes::Yes;
                }
                break;

            case fieldNum(BDRFieldValue, KeyFieldName):
                if (!this.KeyFieldName)
                {
                    this.KeyValue = '';
                }
                break;
        }
    }
